import{j as e}from"./blog-pages-CPaMOKsP.js";import{I as a}from"./I18nErpPage-DpeGnoBT.js";import"./PillarHubNav-Bef1r64A.js";import"./badge-DyJEh5NS.js";const i={heroBadge:"Sistema de gestión de inspección END",heroTitle:"Software ERP de Ensayos No Destructivos en Buenos Aires",heroSubtitle:"Sistema integral de gestión de inspección",heroIntro:"ERP especializado para empresas de Ensayos No Destructivos que operan en el Área Metropolitana de Buenos Aires y la Patagonia argentina. Automatice el seguimiento de certificaciones IRAM-IAS y la programación de inspecciones API.",ctaPrimary:"Solicitar demostración para Buenos Aires",ctaSecondary:"English version",statCompanies:"Empresas END usando Atlantis ERP",statRating:"Calificación promedio de clientes",statAdminReduction:"Reducción en tiempo administrativo",statModules:"Módulos centrales para END",marketContextLabel:"Contexto del mercado END",painPointsTitle:"Por qué los equipos END en Buenos Aires eligen Atlantis ERP",painPointsSubtitle:"Tres puntos críticos de operación eliminados desde el día uno",problemLabel:"El problema",solutionLabel:"La solución",modulesTitle:"Seis módulos centrales para empresas de inspección END",modulesSubtitle:"Cada módulo está diseñado específicamente para la industria de inspección",roiTitle:"ROI de Atlantis ERP en Buenos Aires",faqTitle:"Preguntas frecuentes — Atlantis NDT ERP en Buenos Aires",alsoServingTitle:"También servimos",finalCtaTitle:"¿Listo para modernizar sus operaciones END en Buenos Aires?",finalCtaBody:"Únase a las empresas de inspección en Buenos Aires, La Plata, Bahía Blanca y la cuenca neuquina de Vaca Muerta que han modernizado sus operaciones con Atlantis NDT ERP.",finalCtaPrimary:"Solicitar demostración",finalCtaSecondary:"View English version",switchLangLabel:"English version"};function t(){return e.jsx(a,{lang:"es",dir:"ltr",city:"Buenos Aires",countryCode:"AR",countryName:"Argentina",slug:"ndt-erp-buenos-aires",canonicalPath:"/es/ndt-erp-buenos-aires",englishPath:"/ndt-erp-buenos-aires",pageTitle:"Software ERP END en Buenos Aires | Gestión de Inspección Industrial | Atlantis NDT",pageDescription:"Software ERP de Ensayos No Destructivos para empresas de inspección en Buenos Aires y Argentina. Seguimiento de certificaciones IRAM-IAS, programación API 510/570/653 y reportes YPF.",keywords:"software END Buenos Aires, ERP Argentina, IRAM-IAS, ASNT, API 510, YPF, Vaca Muerta, Neuquén, Bahía Blanca, La Plata refinería",marketContext:"Buenos Aires actúa como el centro administrativo de la industria argentina de hidrocarburos, albergando las oficinas centrales de YPF, Pan American Energy, Tecpetrol y las principales empresas de inspección que dan servicio a la refinería de La Plata, el polo petroquímico de Bahía Blanca y la creciente cuenca neuquina de Vaca Muerta, una de las formaciones de shale más prometedoras del mundo fuera de Estados Unidos. Las empresas de Ensayos No Destructivos argentinas que operan desde Buenos Aires deben gestionar las certificaciones del Instituto Argentino de Normalización y Certificación (IRAM-IAS), las certificaciones internacionales ASNT SNT-TC-1A e ISO 9712, además del cumplimiento con las resoluciones de la Secretaría de Energía de la Nación para inspección de instalaciones petrolíferas. Atlantis NDT ERP proporciona a los equipos de inspección porteños una plataforma unificada para el seguimiento integrado de certificaciones IRAM-IAS y ASNT, la programación automatizada de inspecciones según API 510 para recipientes a presión y API 570 para piping, y la generación de reportes PDF compatibles con los estándares internos de YPF Downstream y los requisitos del Ente Nacional Regulador del Gas (ENARGAS) para infraestructura de gas natural. El sistema también soporta las particularidades de la operación en Vaca Muerta, incluyendo el seguimiento de inspecciones rotacionales fly-in/fly-out a Añelo y los requisitos específicos de los operadores de shale de la cuenca neuquina.",roiBody:"Los clientes de Atlantis NDT ERP en Buenos Aires reportan una reducción del 38% en tiempo administrativo durante los primeros seis meses, con el tiempo de elaboración de un reporte API 570 reducido de cuatro horas a menos de cinco minutos. Las alertas automáticas eliminan los incidentes de caducidad de certificaciones IRAM-IAS y ASNT en equipos rotativos que trabajan en Vaca Muerta, y la preparación de paquetes de auditoría para revisiones de YPF y la Secretaría de Energía pasa de varios días a un solo clic. Para un equipo de inspección de doce técnicos que da servicio a la cuenca neuquina y al polo de Bahía Blanca, esto representa un ahorro anual estimado entre 22.000 y 32.000 dólares estadounidenses en sobrecarga administrativa recuperable, además del valor preventivo de evitar la pérdida de habilitación como proveedor de YPF.",painPoints:[{title:"Operaciones fly-in/fly-out a Vaca Muerta",problem:"Los técnicos de inspección que rotan entre Buenos Aires y los yacimientos de Vaca Muerta en Neuquén enfrentan desafíos logísticos para mantener actualizados los registros de certificación, asignaciones a pozos y datos de inspección en una operación con conectividad limitada.",solution:"Atlantis ERP funciona offline en campo en Añelo, Loma Campana y Bandurria, sincronizando automáticamente al regreso a Neuquén capital o Buenos Aires, con paneles de control que rastrean rotaciones FIFO y disponibilidad de técnicos."},{title:"Cumplimiento dual IRAM-IAS y ASNT",problem:"Las empresas de inspección argentinas deben mantener simultáneamente las certificaciones IRAM-IAS para clientes locales y ASNT para clientes internacionales que operan en Argentina, duplicando los registros y aumentando el riesgo de inconsistencias.",solution:"El sistema mantiene una matriz unificada de certificaciones por técnico que muestra simultáneamente sus calificaciones IRAM-IAS y ASNT, con alertas independientes para cada vencimiento."},{title:"Reportes manuales para YPF",problem:"Los equipos de inspección en Buenos Aires invierten horas reformateando reportes API al formato interno requerido por YPF Downstream para inspecciones en la refinería de La Plata y el complejo industrial Ensenada.",solution:"Genere un reporte completo en formato YPF con su logotipo corporativo y firma digital en menos de cinco minutos directamente desde los datos capturados en campo."}],modules:[{title:"Programación de inspección y órdenes de trabajo",description:"Automatice el cálculo de intervalos según API 510, API 570, API 653 y los intervalos basados en riesgo (RBI) específicos de operadores de Vaca Muerta. Asigne técnicos rotativos FIFO en segundos.",features:["Cálculo automático de intervalos API","Programación RBI","Matriz de disponibilidad FIFO","Flujos de aprobación YPF","Acceso móvil offline en Vaca Muerta"]},{title:"Seguimiento de certificaciones del personal",description:"Centralice registros de certificaciones IRAM-IAS, ASNT SNT-TC-1A, ISO 9712 y calificaciones específicas de YPF y Pan American Energy.",features:["Alertas de vencimiento IRAM-IAS y ASNT","Seguimiento ISO 9712","Matriz de calificaciones por cliente","Recordatorios automáticos de renovación","Exportación PDF para auditoría"]},{title:"Generación de reportes de inspección",description:"Genere reportes profesionales según API 510, API 570, API 653, ASME Sección VIII y formatos específicos de YPF Downstream y los operadores de Vaca Muerta.",features:["Plantillas API 510 para recipientes a presión","Formatos API 570 para piping","Reportes API 653 para tanques","Constructor de plantillas YPF","Integración de firma digital"]},{title:"Gestión de datos de corrosión",description:"Registre mediciones de espesor y cálculos de vida remanente para activos de YPF en La Plata, polos químicos de Bahía Blanca y wellpads de Vaca Muerta.",features:["Base de datos de mediciones de espesor","Gráficos de tendencia de corrosión","Cálculo de vida remanente","Alertas de pérdida de pared","Exportación API 579"]},{title:"Registro de activos y equipos",description:"Mantenga un registro digital completo de activos en La Plata, Plaza Huincul, Loma Campana y Bandurria Sur. Rastree calibraciones según INTI argentino.",features:["Jerarquía de activos P&ID","Calibraciones INTI","Etiquetado QR de activos","Historial de inspección por activo","Clasificación de riesgo"]},{title:"Tablero de cumplimiento",description:"Visibilidad en tiempo real del cumplimiento con resoluciones de la Secretaría de Energía y ENARGAS argentino.",features:["Alertas de inspecciones vencidas","Vista multi-cliente","KPIs de cumplimiento","Alertas de cambios regulatorios","Reportes ejecutivos"]}],integrations:["Formatos de reporte YPF Downstream","Certificaciones IRAM-IAS","Calibración INTI","Reportes Secretaría de Energía","Cumplimiento ENARGAS para gas natural","Integración SAP S/4HANA","Formatos Pan American Energy y Tecpetrol","Soporte FIFO para operaciones en Vaca Muerta"],faqs:[{question:"¿El sistema soporta operaciones fly-in/fly-out a Vaca Muerta?",answer:"Sí. Atlantis ERP incluye un módulo específico para operaciones FIFO que rastrea las rotaciones de técnicos entre Buenos Aires, Neuquén capital y los yacimientos de shale en Añelo, Loma Campana, Bandurria Sur y Fortín de Piedra. El sistema mantiene paneles de control que muestran la disponibilidad de técnicos por semana de rotación, sus certificaciones vigentes para cada operador (YPF, Vista Oil & Gas, Pan American Energy, Tecpetrol), y permite la captura de datos sin conexión en campo."},{question:"¿Cómo se integra el sistema con las certificaciones IRAM-IAS?",answer:"El módulo de personal incluye campos específicos para registrar certificaciones IRAM-IAS según las normas argentinas, con fechas de emisión, vencimiento, métodos calificados (UT, RT, MT, PT, VT, ET) y referencias a los exámenes prácticos. El sistema mantiene archivos digitales de los certificados listos para presentación en auditorías de YPF, Pan American Energy y otros operadores argentinos."},{question:"¿El sistema cumple con las resoluciones de la Secretaría de Energía argentina?",answer:"Sí. El módulo de cumplimiento incluye seguimiento de las resoluciones aplicables de la Secretaría de Energía de la Nación para inspección de instalaciones petrolíferas, incluyendo los requisitos de la Resolución 532/2018 para gestión de integridad mecánica. El sistema mantiene registros auditables para presentación ante autoridades regulatorias provinciales y nacionales."},{question:"¿Se puede operar el sistema con conectividad limitada en Vaca Muerta?",answer:"Sí. La aplicación móvil incluye modo offline completo para captura de datos en yacimientos de la cuenca neuquina donde la conectividad es intermitente. Los datos se sincronizan automáticamente cuando el técnico regresa a la oficina de Neuquén o Buenos Aires, sin pérdida de información incluso después de turnos de catorce días en campo."}],ui:i})}export{t as default};
